    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The abstract explicitly describes the current state of knowledge regarding limited evidence for evaluating sustainability."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used. Our review offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.",
      "reason": "The abstract explains the importance and need for the review by highlighting the lack of clarity on effective approaches and the need for recommendations."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The discussion section explicitly differentiates this review from previous syntheses and cites them, explaining the need for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is an integrative review of evaluation approaches, not a review of intervention effects, so describing the mechanism of action of an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on evaluation methodologies rather than testing complex interventions, so a logic model for intervention components is not applicable to the rationale."
    }
  ],
  "confidence": 85
}

